"""Compact mobile navigation, grouped filters and incremental ratings states."""
UI=r'''
<style>
#browse-view>.hero{display:none!important}.topbar{min-height:48px!important;padding-block:2px!important;gap:8px}.topbar .brand img{width:104px}.topbar nav{justify-content:flex-end}.topbar nav>button,.topbar nav>.header-more{display:none!important}.mobile-menu summary{min-height:44px;padding:12px;cursor:pointer;list-style:none}.mobile-menu{position:relative}.mobile-menu-items{position:absolute;right:0;top:100%;display:grid;min-width:160px;padding:6px;background:var(--surface);border:1px solid var(--border);border-radius:10px;z-index:40}.mobile-menu-items button{text-align:left;min-height:44px}.ingress-host .topbar,.ingress-host .detail-toolbar{padding-top:2px!important}.shell{padding-top:6px!important;padding-inline:12px!important}.media-switch{margin-top:0!important}.searchbar{margin:8px 0!important}.filters{margin-bottom:6px!important}.heading{margin:10px 0!important}.heading h2{font-size:1.2rem}.mobile-filter-toggle{margin-bottom:6px!important}.catalogue-notice{font-size:.76rem;line-height:1.4;overflow-wrap:anywhere}.movies{gap:10px!important}.movie-meta{font-size:.73rem}.compact-ratings{display:flex;flex-wrap:wrap;align-items:center;gap:5px 9px;line-height:1.4;margin:8px 0;font-size:.78rem}.rating-indicator{display:inline-flex;align-items:center;gap:4px;border-bottom:1px solid var(--border);padding:3px 0;white-space:nowrap}.rating-indicator strong{font-weight:850}.rating-hint{color:var(--muted);font-size:.7rem}.ratings-grid,.rating-card{display:none!important}.detail-copy>.rt-score{display:none}.detail-copy h2{font-size:clamp(1.6rem,5vw,2.3rem)!important}.detail-hero{min-height:200px!important;padding:16px!important}.detail-body{padding-inline:14px!important}.detail-grid{gap:8px!important}.rating-filters{display:grid;gap:8px;grid-column:1/-1}.rating-filter-group{border:1px solid var(--border);border-radius:10px;padding:8px}.rating-filter-head{display:flex;justify-content:space-between;align-items:center}.rating-filter-controls{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;margin-top:8px}.rating-filter-controls input{min-width:0;width:100%;padding:9px;font-size:16px}.rating-filter-controls .field{font-size:.7rem}.mobile-filter-panel{display:flex;flex-direction:column;max-height:90dvh!important;padding:0!important}.mobile-filter-head{flex:none;margin:0!important;padding:10px 12px;background:var(--surface);border-bottom:1px solid var(--border)}.mobile-filter-fields{overflow-y:auto;min-height:0;padding:10px 12px;overscroll-behavior:contain}.mobile-filter-actions{flex:none;position:static!important;margin:0;padding:10px 12px calc(10px + env(safe-area-inset-bottom))!important;border-top:1px solid var(--border);display:grid;grid-template-columns:1fr 1fr}.mobile-filter-actions .button{min-height:44px}.mobile-filter-toggle{display:inline-flex!important}.discovery-tools{display:none!important}.provider-status{white-space:pre-wrap;font-size:.78rem;color:var(--muted)}.detail-toolbar nav{margin-bottom:0!important}.detail-toolbar{padding:4px 10px!important}.detail-controls .button,.detail-controls .mobile-modal-back{min-height:40px!important}.movie .compact-ratings{font-size:.7rem;margin:3px 0;gap:3px 6px}.filter-validation{color:var(--danger);font-size:.78rem;padding:6px;grid-column:1/-1}.enrich-button{min-height:44px;margin-block:5px}.ratings-unrated{font-size:.7rem;color:var(--warning)}
@media(max-width:380px){.topbar .brand img{width:96px}.compact-ratings{font-size:.72rem;gap:4px 7px}.rating-filter-controls{grid-template-columns:1fr 1fr}.movie-title{font-size:.85rem}.detail-toolbar nav button{font-size:.8rem;padding:8px}}
</style>
<script>
(function(){
const q=id=>document.getElementById(id),sources={tmdb:['TMDb',10],imdb:['IMDb',10],rt_critic:['RT critics',100],rt_audience:['RT audience',100],metacritic:['MC',100],letterboxd:['Letterboxd',5],trakt:['Trakt',10]},ratingCache=new Map();
if(window.self!==window.top)document.body.classList.add('ingress-host');
const header=document.querySelector('.topbar nav'),menu=document.createElement('details');menu.className='mobile-menu';menu.innerHTML='<summary aria-label="Open MediaHub navigation">☰</summary><div class="mobile-menu-items"></div>';header.append(menu);const entries=menu.querySelector('div');const browse=document.createElement('button');browse.textContent='Browse';browse.onclick=()=>{showView('browse');menu.open=false;};entries.append(browse);for(const button of [...header.querySelectorAll('button')]){if(button.dataset.view==='browse')continue;entries.append(button);button.addEventListener('click',()=>menu.open=false);}
function ratingRow(matrix,kind='detail'){const verified=Object.entries(sources).filter(([id])=>matrix?.[id]?.status==='verified'&&matrix[id].value!=null);return `<div class="compact-ratings" aria-label="Verified ratings">${verified.map(([id,[label,scale]])=>{const r=matrix[id];const stamp=r.retrieved?new Date(r.retrieved*1000).toLocaleString():'';return `<span class="rating-indicator" title="${esc(`${label}, via ${r.provider||'TMDb'}${r.votes!=null?', '+r.votes.toLocaleString()+' votes':''}${stamp?', retrieved '+stamp:''}`)}"><span>${esc(label)}</span><strong>${Number(r.value).toFixed(scale===100?0:1)}${id.startsWith('rt_')?'%':scale===100?'/100':scale===5?'/5':''}</strong></span>`;}).join('')}${!verified.length?'<span class="rating-hint">Ratings awaiting retrieval</span>':''}</div>`;}
function detailRatings(){const movie=state.movie,detail=q('detail');if(!movie||!detail.querySelector('.detail-copy'))return;detail.querySelectorAll('.ratings-grid,.detail-copy>.rt-score').forEach(node=>node.remove());let matrix=ratingCache.get(`${movie.media_type==='tv'?'tv':'movie'}:${movie.tmdb_id}`)||{};if(!matrix.tmdb&&movie.rating!=null)matrix={...matrix,tmdb:{status:'verified',value:movie.rating,provider:'tmdb',votes:movie.vote_count}};let row=detail.querySelector('.multi-ratings');if(!row){row=document.createElement('div');row.className='multi-ratings';detail.querySelector('.detail-copy').append(row);}const html=ratingRow(matrix);if(row.innerHTML!==html)row.innerHTML=html;}
const renderMovieBefore=renderDetail;renderDetail=function(){renderMovieBefore();detailRatings();attachDiagnostics();};const renderTvBefore=renderTvDetail;renderTvDetail=function(show){renderTvBefore(show);detailRatings();};
let refreshingRatings=false;new MutationObserver(()=>{if(refreshingRatings)return;refreshingRatings=true;requestAnimationFrame(()=>{refreshingRatings=false;detailRatings();});}).observe(q('detail'),{childList:true});
let ratingsConfigured=false;const previousApi=api;api=async function(path,options={}){
 if(path==='critic-ratings'){const payload=JSON.parse(options.body||'{}');const response=await previousApi('ratings',options);ratingsConfigured=!!response.configured;for(const [id,matrix] of Object.entries(response.ratings||{}))ratingCache.set(`${payload.media_type}:${id}`,matrix);detailRatings();return {scores:Object.fromEntries(Object.entries(response.ratings||{}).map(([id,matrix])=>[id,matrix.rt_critic?.status==='verified'?matrix.rt_critic.value:null])),configured:response.configured};}
 if(/^catalog\/(movies|tv)\?/.test(path)){const kind=path.startsWith('catalog/movies')?'movies':'tv',params=new URLSearchParams(path.split('?')[1]);const s=currentCatalogueState();params.set('ratings',JSON.stringify(s.multiRatings||{}));params.set('sort',s.ratingSort||'popular');params.set('missing',s.missingRatings||'exclude');for(const [key,value] of Object.entries(s.advancedDiscovery||{}))if(value)params.set(key,value);const data=await previousApi(`discovery/${kind}?${params}`,options);window.MEDIAHUB_RATING_COVERAGE=data.coverage||null;setTimeout(()=>coverageControls(data,params,kind),0);return data;}
 return previousApi(path,options);
};

let ratingPollRunning=false;setInterval(async()=>{if(ratingPollRunning||document.hidden||!ratingsConfigured)return;const detailOpen=!q('modal').classList.contains('hidden');if(!detailOpen&&state.view!=='browse')return;const kind=detailOpen?(state.movie?.media_type==='tv'?'tv':'movie'):browseMedia,ids=detailOpen?[state.movie?.tmdb_id]:[...q('movies').querySelectorAll('[data-id],[data-tv-id]')].slice(0,20).map(card=>Number(card.dataset.id||card.dataset.tvId));if(!ids.length||!ids[0])return;ratingPollRunning=true;try{const data=await previousApi('ratings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({media_type:kind,ids})});ratingsConfigured=!!data.configured;for(const [id,matrix] of Object.entries(data.ratings||{})){ratingCache.set(`${kind}:${id}`,matrix);const card=q('movies').querySelector(`[${kind==='tv'?'data-tv-id':'data-id'}="${id}"]`),target=card?.querySelector('.card-ratings');if(target){const html=ratingRow(matrix,'card');if(target.innerHTML!==html)target.innerHTML=html;}}detailRatings();}catch(_){}finally{ratingPollRunning=false;}},10000);
const appendBefore=appendUnique;appendUnique=function(items,cardFn,idFn,reset=false){appendBefore(items,cardFn,idFn,reset);for(const item of items){const kind=browseMedia,card=q('movies').querySelector(`[${kind==='tv'?'data-tv-id':'data-id'}="${item.tmdb_id}"]`);if(!card)continue;const metadata=card.querySelector('.movie-meta');if(metadata)metadata.textContent=`${kind==='tv'?'TV · ':''}${item.year||''}`;card.querySelectorAll('.rt-score,.card-ratings').forEach(node=>node.remove());const matrix=item.ratings_data||ratingCache.get(`${kind}:${item.tmdb_id}`)||{tmdb:{status:'verified',value:item.rating,provider:'tmdb'}};card.insertAdjacentHTML('beforeend',`<div class="card-ratings">${ratingRow(matrix,'card')}${item.ratings_incomplete?'<span class="ratings-unrated">Some ratings unverified</span>':''}</div>`);}};
function coverageControls(data,params,kind){if(!data.coverage){q('enrich-ratings')?.remove();return;}let notice=q('rt-catalogue-notice');if(!notice)return;let button=q('enrich-ratings');if(!button){button=document.createElement('button');button.id='enrich-ratings';button.className='button enrich-button';notice.after(button);}button.textContent='Enrich this discovery';button.onclick=async()=>{button.disabled=true;button.textContent='Inspecting candidates...';try{const result=await previousApi(`discovery/${kind}/enrich?${params}`,{method:'POST'});toast(`${result.inspected} candidates inspected. Ratings will update in the background.`);await loadCataloguePage(1,{reset:true});}catch(error){toast(error.message,'error');}finally{button.disabled=false;button.textContent='Enrich this discovery';}};if(!q('refresh-rating-results')){const refresh=document.createElement('button');refresh.id='refresh-rating-results';refresh.className='button';refresh.textContent='Refresh results';button.after(refresh);refresh.onclick=()=>loadCataloguePage(1,{reset:true});}}
const fields=q('mobile-filter-fields'),groups=document.createElement('div');groups.className='rating-filters';groups.innerHTML=Object.entries(sources).map(([id,[name,scale]])=>`<fieldset class="rating-filter-group" data-rating-source="${id}"><div class="rating-filter-head"><label><input type="checkbox" data-rating-enabled> ${name}${scale===100?' (%)':` (/${scale})`}</label><button class="button" type="button" data-rating-clear aria-label="Clear ${name}">Clear</button></div><div class="rating-filter-controls"><label class="field">Minimum<input type="number" min="0" max="${scale}" step="${scale===100?1:0.1}" data-rating-min></label><label class="field">Maximum<input type="number" min="0" max="${scale}" step="${scale===100?1:0.1}" data-rating-max></label>${['tmdb','imdb'].includes(id)?'<label class="field">Minimum votes<input type="number" min="0" step="1" data-rating-votes></label>':''}</div></fieldset>`).join('')+'<label class="field">Unverified ratings<select id="missing-ratings"><option value="exclude">Exclude unverified titles</option><option value="include">Include unverified titles (labelled)</option></select></label><label class="field">Sort<select id="ratings-sort">'+[['popular','Most popular'],['tmdb','Highest TMDb'],['imdb','Highest IMDb'],['rt_critic','Highest RT critics'],['rt_audience','Highest RT audience'],['metacritic','Highest Metacritic'],['letterboxd','Highest Letterboxd'],['trakt','Highest Trakt'],['reviewed','Most reviewed (TMDb)'],['newest','Newest'],['oldest','Oldest'],['added','Recently inspected']].map(([v,label])=>`<option value="${v}">${label}</option>`).join('')+'</select></label>'+[['language','Original language (ISO code)'],['country','Origin country (ISO code)'],['runtime_min','Minimum runtime (minutes)'],['runtime_max','Maximum runtime (minutes)']].map(([id,label])=>`<label class="field">${label}<input id="advanced-${id}" ${id.startsWith('runtime')?'type="number" min="0"':'maxlength="2"'}></label>`).join('')+'<label><input type="checkbox" id="advanced-streaming_au"> Subscription streaming in Australia (TMDb availability)</label><div id="rating-filter-error" class="filter-validation" role="alert"></div>';
fields.append(groups);fields.querySelectorAll('[id="mobile-rating-from"],[id="mobile-rating-to"],[id="mobile-rt-min"],[id="mobile-rt-max"]').forEach(el=>el.closest('label').style.display='none');groups.querySelectorAll('[data-rating-clear]').forEach(button=>button.onclick=()=>{const field=button.closest('fieldset');field.querySelector('[data-rating-enabled]').checked=false;field.querySelectorAll('input[type="number"]').forEach(input=>input.value='');});
q('mobile-filter-toggle').addEventListener('click',()=>{const s=currentCatalogueState();for(const field of groups.querySelectorAll('fieldset')){const rule=s.multiRatings?.[field.dataset.ratingSource]||{};field.querySelector('[data-rating-enabled]').checked=!!s.multiRatings?.[field.dataset.ratingSource];for(const [name,selector] of [['min','[data-rating-min]'],['max','[data-rating-max]'],['votes','[data-rating-votes]']]){const input=field.querySelector(selector);if(input)input.value=rule[name]??'';}}const selectedGenres=new Set((s.genres?.length?s.genres:s.genre?[s.genre]:[]).map(String));q('mobile-genre-list')?.querySelectorAll('input').forEach(input=>input.checked=selectedGenres.has(input.value));q('missing-ratings').value=s.missingRatings||'exclude';q('ratings-sort').value=s.ratingSort||'popular';for(const id of ['language','country','runtime_min','runtime_max','streaming_au']){const input=q('advanced-'+id);if(input.type==='checkbox')input.checked=s.advancedDiscovery?.[id]==='true';else input.value=s.advancedDiscovery?.[id]||'';}q('rating-filter-error').textContent='';});
q('mobile-filter-apply').addEventListener('click',event=>{const rules={};try{for(const field of groups.querySelectorAll('fieldset')){if(!field.querySelector('[data-rating-enabled]').checked)continue;const id=field.dataset.ratingSource,rule={};for(const [name,selector] of [['min','[data-rating-min]'],['max','[data-rating-max]'],['votes','[data-rating-votes]']]){const input=field.querySelector(selector);if(input?.value!==' '&&input?.value){const number=Number(input.value);if(!Number.isFinite(number)||number<0||name!=='votes'&&number>sources[id][1]||name==='votes'&&!Number.isInteger(number))throw new Error(`Invalid ${sources[id][0]} ${name}.`);rule[name]=number;}}if(rule.min!=null&&rule.max!=null&&rule.min>rule.max)throw new Error(`${sources[id][0]} minimum exceeds maximum.`);if(Object.keys(rule).length)rules[id]=rule;}const s=currentCatalogueState();s.multiRatings=rules;s.ratingSort=q('ratings-sort').value;s.missingRatings=q('missing-ratings').value;s.advancedDiscovery={};for(const id of ['language','country','runtime_min','runtime_max','streaming_au']){const input=q('advanced-'+id);s.advancedDiscovery[id]=input.type==='checkbox'?(input.checked?'true':''):input.value;}if(Object.keys(rules).length){q('mobile-rt-min').value='';q('mobile-rt-max').value='';q('rt-min').value='';q('rt-max').value='';}}catch(error){event.stopImmediatePropagation();q('rating-filter-error').textContent=error.message;}},true);
q('mobile-filter-clear').addEventListener('click',()=>{groups.querySelectorAll('input').forEach(input=>{if(input.type==='checkbox')input.checked=false;else input.value='';});q('ratings-sort').value='popular';q('missing-ratings').value='exclude';q('rating-filter-error').textContent='';});
function activeCount(){q('mobile-filter-toggle').setAttribute('aria-label','Open discovery filters');}
q('mobile-filter-apply').addEventListener('click',()=>requestAnimationFrame(activeCount));
const setup=document.querySelector('#setup-view .setup-grid');setup.insertAdjacentHTML('beforeend','<section class="service" id="ratings-provider-panel"><div class="service-head">Ratings providers</div><label class="field">MDBList API key<input id="mdblist_api_key" type="password" autocomplete="new-password"></label><button class="button" id="save-mdblist">Save MDBList key</button><button class="button" data-test-provider="mdblist">Test MDBList</button><button class="button" data-test-provider="omdb">Test OMDb</button><label class="field">Cache expiry (days)<input id="ratings-cache-days" type="number" min="1" max="30" value="7"></label><label class="field">Daily budget per external provider<input id="ratings-budget" type="number" min="0" max="900" value="400"></label><label><input id="ratings-background" type="checkbox" checked> Background enrichment</label><button class="button" id="save-ratings-config">Save ratings configuration</button><pre class="provider-status" id="ratings-provider-health"></pre><p class="hint">TMDb remains the catalogue. External keys are optional. Source availability and account limits vary; no paid tier is required for core functionality.</p></section>');
async function updateHealth(){try{const data=await previousApi('ratings/health');q('ratings-provider-health').textContent=Object.entries(data.providers).map(([name,p])=>`${name}: ${p.status}\nLast success: ${p.last_success?new Date(p.last_success*1000).toLocaleString():'not yet'}\nLast error: ${p.last_error||'none'}`).join('\n\n')+`\n\nQueue: ${JSON.stringify(data.jobs)}`;q('ratings-cache-days').value=data.configuration.cache_days;q('ratings-budget').value=data.configuration.daily_budget;q('ratings-background').checked=data.configuration.background_enabled;q('ratings-provider-health').textContent+=`\n\nCoverage: ${JSON.stringify(data.coverage)}`;}catch(error){q('ratings-provider-health').textContent=error.message;}}
q('save-mdblist').onclick=async()=>{try{await previousApi('setup/integrations',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({updates:{mdblist_api_key:q('mdblist_api_key').value}})});q('mdblist_api_key').value='';await updateHealth();toast('MDBList key saved.');}catch(error){toast(error.message,'error');}};setup.querySelectorAll('[data-test-provider]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{const data=await previousApi(`ratings/providers/${button.dataset.testProvider}/test`,{method:'POST'});toast(`${button.dataset.testProvider}: ${data.status}`);await updateHealth();}catch(error){toast(error.message,'error');}finally{button.disabled=false;}});q('save-ratings-config').onclick=async()=>{try{await previousApi('ratings/configuration',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({cache_days:Number(q('ratings-cache-days').value),daily_budget:Number(q('ratings-budget').value),background_enabled:q('ratings-background').checked})});toast('Ratings configuration saved.');}catch(error){toast(error.message,'error');}};const setupBefore=loadSetup;loadSetup=async function(){await setupBefore();await updateHealth();};
function attachDiagnostics(){if(state.user?.role!=='admin'||state.movie?.media_type==='tv'||q('release-diagnostics'))return;const area=q('release-area');if(!area)return;const box=document.createElement('details');box.id='release-diagnostics';box.innerHTML='<summary>Administrator release diagnostics</summary><button class="button" type="button">Run read-only diagnostics</button><pre class="provider-status" aria-live="polite"></pre>';area.after(box);const id=state.movie.tmdb_id;box.querySelector('button').onclick=async event=>{event.target.disabled=true;try{const result=await previousApi(`diagnostics/movies/${id}/releases`);box.querySelector('pre').textContent=JSON.stringify(result,null,2);}catch(error){box.querySelector('pre').textContent=error.message;}finally{event.target.disabled=false;}};}
})();
</script>
'''
